import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {createDevSession,recommendedDevParty,devChapterCatalog} from '../dev-session.js';
import {World} from '../world.js';import {Battle,encounterEnemies} from '../battle.js?v=5.6.0';import {compileTechnique,CORES,SUPPORTS} from '../mako.js';import {findPath} from '../navigation.js';import {resolveGuidedObjective} from '../guided-objective.js';
const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));
test('developer catalogue is lightweight, bounded and covers each authored guardian',()=>{const catalogue=devChapterCatalog(data);assert.equal(catalogue.length,24);for(const [i,c]of catalogue.entries()){assert.equal(c.chapter,i+1);assert.ok(c.name);assert.ok(c.bossName);assert.equal(c.level,i+4);assert.ok(c.level<45);}for(let lead=0;lead<7;lead++){const p=recommendedDevParty(lead);assert.equal(p[0],lead);assert.equal(p.length,3);assert.equal(new Set(p).size,3);if(lead!==1)assert.ok(p.includes(1));}assert.throws(()=>recommendedDevParty(7));});
test('every chapter, arrival/boss stage and lead restores a canonical legal three-person practice state',()=>{const before=JSON.stringify(data),w=new World(data);let cases=0;for(let chapter=1;chapter<=24;chapter++)for(const stage of ['arrival','boss'])for(let lead=0;lead<7;lead++){
 const {save,summary}=createDevSession(data,{chapter,stage,lead});w.restore(save.world);assert.equal(w.state.chapter,chapter);assert.equal(w.state.mode,'field');assert.equal(w.state.party[0],lead);assert.equal(w.state.party.length,3);assert.equal(w.state.heroes[lead].level,chapter+3);assert.equal(w.state.complete,false);assert.deepEqual(w.state.bosses,Array.from({length:chapter-1},(_,i)=>i+1));assert.equal(w.walkable(w.state.x,w.state.y),true);assert.equal(summary.practiceOnly,true);assert.ok(summary.objective);assert.equal(summary.party.length,3);
 for(const h of w.activeHeroes){assert.ok(h.loadout.length>=1&&h.loadout.length<=h.unlockedSlots);assert.ok(h.hp>0&&h.hp===h.maxHp&&h.mp===h.maxMp);for(const slot of h.loadout){assert.ok(CORES.some(c=>c.id===slot.core));assert.ok(SUPPORTS.some(s=>s.id===slot.support));assert.ok(w.state.cores.includes(slot.core)&&w.state.supports.includes(slot.support));const t=compileTechnique(slot.core,slot.support,{character:h.id,ap:h.ap[slot.core]});assert.ok(t.cost>0&&t.cost<=h.maxMp);}for(const item of Object.values(w.state.items))assert.ok(Number.isInteger(item)&&item>=0&&item<=20);}
 if(stage==='boss'){const boss=w.objects().find(o=>o.type==='boss');assert.ok(boss,'guardian in correct room '+chapter);assert.ok(boss.requires===undefined||w.bit(w.mission.flag_address,boss.requires));assert.ok((boss.requires_flags||[]).every(f=>w.bit(...f)));assert.ok(findPath(w.scene,[w.state.x,w.state.y],boss.xy,1).length||Math.hypot(w.state.x-boss.xy[0]-.5,w.state.y-boss.xy[1]-.5)<2);w.interact(boss);assert.ok(w.currentBattle,'legal guardian interaction '+chapter);}
 cases++;
 }assert.equal(cases,336);assert.equal(JSON.stringify(data),before);});
test('alternate branch fixtures retain meaningful earlier decisions without claiming the current guardian or sharing mutable state',()=>{for(const branch of [0,1]){const a=createDevSession(data,{chapter:24,stage:'boss',lead:6,party:[4,6,3],branch});assert.deepEqual(a.save.world.party,[6,4,3]);for(const value of Object.values(a.save.world.storyChoices))if(value!==null)assert.equal(value,branch);assert.equal(a.save.world.bosses.includes(24),false);assert.ok(a.summary.party.every(h=>h.equipment.every(g=>g.id!=='guardian-24')));a.save.world.items.tonic=999;const b=createDevSession(data,{chapter:24,stage:'boss',branch});assert.ok(b.save.world.items.tonic<=20);}});
test('practice kits can resolve all 24 isolated guardian baselines using only equipped recipes and resource-paying commands',()=>{for(let chapter=1;chapter<=24;chapter++){
 const {save}=createDevSession(data,{chapter,stage:'boss'}),w=new World(data);w.restore(save.world);const heroes=w.activeHeroes;heroes.forEach((h,i)=>{h.x=i;h.y=0;});const enemies=encounterEnemies(chapter,true);enemies.forEach((e,i)=>{e.x=4+i;e.y=0;});const b=new Battle({heroes,enemies,chapter,rng:()=>.5});let paid=0;
 for(let n=0;n<15000&&!b.ended;n++){b.advance(.1);for(const h of b.ready){const low=[...heroes].filter(a=>a.hp>0).sort((a,c)=>a.hp/a.maxHp-c.hp/c.maxHp)[0],techs=h.loadout.map(slot=>compileTechnique(slot.core,slot.support,{character:h.id,ap:h.ap[slot.core]||0})),heal=techs.find(t=>t.healing&&t.core==='mend'),damage=techs.find(t=>t.interrupt&&!t.healing)||techs.find(t=>!t.healing);if(heal&&low.hp<low.maxHp*.7&&h.mp>=heal.cost&&h.strain<75){const mp=h.mp;if(b.command(h.id,'tech',low.id,heal)){assert.ok(h.mp<mp);paid++;}}else if(damage&&h.mp>=damage.cost&&h.strain<65){const mp=h.mp;if(b.command(h.id,'tech',b.livingEnemies[0]?.id,damage)){assert.ok(h.mp<mp);paid++;}}else b.command(h.id,'guard',h.id);}}
 assert.equal(b.ended,'win','guardian '+chapter);assert.ok(paid>0);assert.ok(heroes.every(h=>Number.isFinite(h.hp)&&h.mp>=0));
 }});
test('invalid or ambiguous practice requests fail without constructing or altering a normal journey',()=>{for(const options of [{chapter:0},{chapter:25},{stage:'ending'},{lead:9},{branch:2},{party:[0,0,1]},{lead:4,party:[0,1,2]}])assert.throws(()=>createDevSession(data,options));});
test('practice construction neither touches browser storage nor changes an already-running normal journey',()=>{const live=new World(data),before=live.save(),descriptor=Object.getOwnPropertyDescriptor(globalThis,'localStorage');let reads=0;Object.defineProperty(globalThis,'localStorage',{configurable:true,get(){reads++;throw Error('Normal save storage must not be accessed by the practice factory');}});try{const {save}=createDevSession(data,{chapter:12,stage:'boss',lead:4});assert.equal(save.schema,'ash-aether.enhanced-save/1');assert.equal(save.world.chapter,12);assert.equal(reads,0);assert.equal(live.save(),before);}finally{if(descriptor)Object.defineProperty(globalThis,'localStorage',descriptor);else delete globalThis.localStorage;}});

test('arrival checkpoints have reachable first objectives and boss checkpoints guide directly to their prepared guardian',()=>{const w=new World(data);for(let chapter=1;chapter<=24;chapter++)for(const stage of ['arrival','boss']){const {save}=createDevSession(data,{chapter,stage});w.restore(save.world);const goal=resolveGuidedObjective(w);assert.ok(goal?.object?.xy,'actionable '+chapter+':'+stage);const distance=Math.hypot(w.state.x-goal.object.xy[0]-.5,w.state.y-goal.object.xy[1]-.5);assert.ok(findPath(w.scene,[w.state.x,w.state.y],goal.object.xy,1).length||distance<2,'reachable '+chapter+':'+stage);if(stage==='boss')assert.equal(goal.object.type,'boss','prepared guardian '+chapter);}});
